// Copies the editor's config schema (src/types/schema.ts) into the package so the
// package validates exactly what LiteEditor accepts. Run with --check in CI.
import { readFileSync, writeFileSync, existsSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

const source = fileURLToPath(new URL('../../../src/types/schema.ts', import.meta.url))
const target = fileURLToPath(new URL('../src/schema.ts', import.meta.url))
const header =
  '// GENERATED by scripts/sync-schema.mjs from src/types/schema.ts. Do not edit.\n'

if (!existsSync(source)) {
  // Building from a published tarball or an isolated checkout: keep the committed copy.
  console.log('sync-schema: editor schema not found, keeping existing copy')
  process.exit(0)
}

const next = header + readFileSync(source, 'utf8')
const current = existsSync(target) ? readFileSync(target, 'utf8') : ''

if (process.argv.includes('--check')) {
  if (current !== next) {
    console.error('src/schema.ts is out of date. Run `npm run sync-schema` and commit the result.')
    process.exit(1)
  }
  console.log('src/schema.ts is up to date')
} else if (current !== next) {
  writeFileSync(target, next)
  console.log('sync-schema: updated src/schema.ts')
}
